			if ( R && cam ) { const h = ( opt( ()=>R.getSize().height * R.getPixelRatio() ) || 900 ) * perfScale(); pointScale = h / ( 2 * Math.tan( ( cam.fov || 45 ) * D2R / 2 ) ); }
