		const value = text( { x: bx + bw + 12, y: y + H / 2, size: 10, align_x: 1, text: '' } );
		const sub = text( { x: cx, y: y + H + 12, size: 11, align_x: 0, text: 'A-04 HANGAR GUARDIAN' } );
		name.nJ( 1, 0.62, 0.56 ); value.nJ( 1, 0.7, 0.64 ); sub.nJ( 1, 0.8, 0.76 );
		return { panel, back, trail, fill, border, notch, name, value, sub, bx, bw, alpha: 0, shown: 0, trailV: 1, hold: 0, gone: 0, boss: null, rageWas: false };
