		const line = pb2Window.CreateWindow( { x: cx - 260, y: 64, w: 520, h: 2, parent: band, type: pb2Window.HUD_RECT, fX: new pb2HighRangeColor().setRGB( col[ 0 ], col[ 1 ], col[ 2 ] ), opacity: 0 } );
		const text = ( o )=>{ const t = jc.pM( Object.assign( { parent: pb2_mp.jk, z: band.dR + 1, dH: 0, dynamic: true, color: new ColorTransform( 1, 1, 1 ) }, o ) ); t.ng( Math.PI, 0, 0 ); t.SetAlpha( 0 ); return t; };
