			if ( !c.intro && s.act === A.INTRO ) { c.intro = true; titleCard( ( s.name || 'Sword Bot' ).toUpperCase(), BAR_SUB[ s.livery ] || BAR_SUB[ 1 ], hexRGB( lookOf( s.livery ).energy ) ); }
			if ( !c.dead && s.act === A.DEATH ) { c.dead = true; titleCard( ( s.name || 'Sword Bot' ).toUpperCase() + ' DESTROYED', 'THE HANGAR IS CLEAR', [ 0.9, 0.9, 0.95 ] ); }
