			g.fillStyle = 'rgba(18,18,20,0.4)'; g.fillRect( 0, h / 2 - 1, w, 2 );
			for ( const [ bx, by ] of [ [ 16, 16 ], [ w - 16, 16 ], [ 16, h - 16 ], [ w - 16, h - 16 ], [ w / 2, 16 ], [ w / 2, h - 16 ], [ 16, h / 2 ], [ w - 16, h / 2 ] ] ) { g.fillStyle = 'rgba(30,30,32,0.9)'; g.beginPath(); g.arc( bx, by, 4, 0, 7 ); g.fill(); g.fillStyle = 'rgba(210,210,215,0.35)'; g.beginPath(); g.arc( bx - 1, by - 1, 2, 0, 7 ); g.fill(); }
