				type: BAR_TYPE_BOOST, title: 'Boost', value: 100, value_max: 100, order: 11,
				color: new pb2HighRangeColor( 0x1f8fff ), color_border: new pb2HighRangeColor( 0x5cb4ff ),
				color_title: new pb2HighRangeColor( 0xaedcff ), color_delta: new pb2HighRangeColor( 0xffffff )
