					color: { value: new THREE.Color( o.color ?? 0xffffff ) }, map: { value: o.map || null }, useMap: { value: o.map ? 1 : 0 },
					uvx: { value: new THREE.Vector4( ...( o.uvx || [ 1, 1, 0, 0 ] ) ) }, emissive: { value: new THREE.Color( o.emissive ?? 0x000000 ) },
					opacity: { value: o.opacity ?? 1 }, shade: { value: 1 }, gloss: { value: o.gloss ?? 0.12 },
					shadowmap: { value: null }, UN: { value: new THREE.Vector4( 0, 0, 1, 1 ) }, dynamic_shadowmap: { value: null }, dKG: { value: new THREE.Vector4( 0, 0, 1, 1 ) }, lit: { value: 0 },
