					if ( /Distance/.test( j.constructor.name ) ) { onHub.x = 0; onHub.y = -j.m_length; onChassis.x = lx; onChassis.y = ly; j.m_frequencyHz = cfg.springHz; j.m_dampingRatio = 0.85; }
