		for ( const b of wheelBodies ) { const fl = fixtures( b ); for ( const f of fl ) f.GetShape().m_radius = ( f === fl[ 0 ] ) ? R : rim; }
		for ( const b of wheelBodies ) { const fl = fixtures( b ); for ( const f of fl ) if ( f !== fl[ 0 ] ) { if ( f.SetFriction ) f.SetFriction( 0 ); else f.m_friction = 0; } }
