		add( 'darker', plate( ssPts( [ [ 249, 196 ], [ 257, 188 ], [ 290, 181 ], [ 292, 186 ], [ 259, 193 ], [ 252, 199 ] ] ), 40, 0.8 ), 0, 2.6, 0 );                 // a recess in it
		for ( const sd of [ -1, 1 ] ) add( 'dark', plate( ssPts( [ [ 262, 186 ], [ 302, 178 ], [ 302, 184 ], [ 264, 191 ] ] ), 8, 1 ), 0, 0.6, sd * 42 );   // its side strakes
