			const wp = parts(), s = ( v )=>v * sd;
			wp( 'skin', flat( [ [ 16, s( -6 ) ], [ 2, s( 130 ) ], [ -22, s( 132 ) ], [ -46, s( 8 ) ], [ -46, s( -6 ) ] ], 3 ), 0, 0, 0 );
			wp( 'light', flat( [ [ 10, s( 20 ) ], [ 0, s( 118 ) ], [ -8, s( 118 ) ], [ -2, s( 20 ) ] ], 3.4 ), 0, 0, 0 );
			wp( 'teal', flat( [ [ -24, s( 12 ) ], [ -16, s( 124 ) ], [ -19, s( 124 ) ], [ -27, s( 12 ) ] ], 3.6 ), 0, 0, 0 );
			wp( sd > 0 ? 'nav' : 'red', cbox( 5, 2.6, 3, 0.5 ), -10, 0, s( 132 ) );
			wp( 'dark', new T.CylinderBufferGeometry( 7, 7, 6, 14 ), 0, 0, 0 );                                        // the pivot
			bake( g, wp, M, [ 'nav', 'red' ] );
			const te = ( z )=>-46 + 24 * ( z - 8 ) / 124;                                                                  // the trailing edge's x at span z
			const f = new T.Group(); f.position.set( te( 14 ), 0, s( 14 ) ); g.add( f );
			const fp = parts();
			fp( 'dark', flat( [ [ 0.6, 0 ], [ te( 100 ) - te( 14 ) + 0.6, s( 86 ) ], [ te( 100 ) - te( 14 ) - 9, s( 86 ) ], [ -11, 0 ] ], 2 ), 0, 0, 0 );
