		root.add( face ); face.add( body );
		const add = parts();
		// a faceted section: ridge, upper chines, the widest chine, lower facets, a flat belly
		const hex = ( cy, h, w )=>[ [ cy + h, 0 ], [ cy + h * 0.5, -w * 0.72 ], [ cy + h * 0.05, -w ], [ cy - h * 0.55, -w * 0.78 ], [ cy - h, -w * 0.32 ], [ cy - h, w * 0.32 ], [ cy - h * 0.55, w * 0.78 ], [ cy + h * 0.05, w ], [ cy + h * 0.5, w * 0.72 ] ];
