			edge( 'red', [ 52, 12, sd * 44.4 ], [ 39, -1.6, sd * 44.4 ], 0.9 ); edge( 'red', [ 39, -1.6, sd * 44.4 ], [ 47, -17, sd * 44.4 ], 0.9 );
			// the chine light under the nose
