		add( 'frameL', sloft( CHIN.map( ( [ x, t, b, w ] )=>[ x, roundPoly( [ [ t - 5, w * 0.8 ], [ ( t + b ) / 2, w ], [ b, w * 0.45 ], [ b, -w * 0.45 ], [ ( t + b ) / 2, -w ], [ t - 5, -w * 0.8 ] ], 2.5, 3 ) ] ) ) );
