			wheel( 134, -24, 21, 22, 'metal' );
			for ( const x of TANK_ROADWHEELS ) wheel( x, -34, 19, 24, 'rubber' );
			for ( const x of [ -60, 40 ] ) wheel( x, -1, 6, 14, 'dark', false );
			for ( const k of Object.keys( still ) ) merged( still[ k ], M[ k ] );
