		add( 'jet.1', 'Air', 3, 'Raven', 'Jet · Style 1', 'Swing-wing fighter for two; rockets and bombs.', JET, 1, ()=>buildJet( 1 ), 60 );
		add( 'jet.2', 'Air', 4, 'Shadow Bird', 'Jet · Style 2', 'Stealth fighter; its bay opens as it fires.', JET, 2, ()=>buildJet( 2 ), 60 );
