const GLOW_FS = `uniform vec3 color; uniform float opacity; varying vec2 vUv;
void main(){ float d = length( vUv - 0.5 ) * 2.0; float k = pow( max( 0.0, 1.0 - d ), 2.2 ); gl_FragColor = vec4( color * k * opacity, 1.0 ); }`;
