					p.z += Math.cos( t * 0.47 + p.phase * 1.3 ) * 0.5 * p.speed * p.hz * dt;
					if ( p.x > p.hx * 1.15 ) p.x = -p.hx * 1.15; else if ( p.x < -p.hx * 1.15 ) p.x = p.hx * 1.15;
					if ( p.z > p.hz ) p.z = -p.hz; else if ( p.z < -p.hz ) p.z = p.hz;
