			uniforms: {
				time: { value: 0 },
				opacity: { value: spec.opacity },
				c1: { value: new T.Color( spec.colors[ 0 ] ) },
				c2: { value: new T.Color( spec.colors[ 1 ] ) },
				c3: { value: new T.Color( spec.colors[ 2 ] ) },
				src: { value: new T.Vector2( ( spec.src || [ 0.8, 0.85 ] )[ 0 ], ( spec.src || [ 0.8, 0.85 ] )[ 1 ] ) }
			},
			vertexShader: baseMaterial().vertexShader,
