		if ( sp.density !== 'off' )
		{
			// one shader layer per kind: a pack's aurora/haze doesn't double the theme's own
			const kinds = new Set();
			const addAmbient = ( s )=>{ if ( !kinds.has( s.kind ) ) { kinds.add( s.kind ); addShaderLayer( s ); } };
			// scene-bound ambience (haze, aurora; legacy inline theme effects)
			if ( th ) { ( th.ambient || th.shaders || [] ).forEach( addAmbient ); ( th.particles || [] ).forEach( addParticles ); }
			// the selected effect packs (petals, bubbles, light rays, lens flare, ...)
			( sp.effects || [] ).forEach( ( pack )=>{ ( pack.shaders || [] ).forEach( addAmbient ); ( pack.particles || [] ).forEach( addParticles ); } );
		}

